<?php foreach ($requests as $request): ?><tr><td><strong><?= esc($request['title']) ?></strong><div class="small text-muted"><?= esc($request['department']) ?> · <?= esc($request['requester_name'] ?: 'Department user') ?></div></td><td><span class="badge bg-primary-subtle text-primary">Submitted</span> → <span class="badge <?= in_array($request['status'], ['transmitted','completed'], true) ? 'bg-primary-subtle text-primary' : 'bg-light text-muted' ?>">Transmitted</span> → <span class="badge <?= $request['status'] === 'completed' ? 'bg-success-subtle text-success' : 'bg-light text-muted' ?>">Completed</span></td><td><?= (int) $request['file_count'] ?></td><td><?php if ($request['transmitter_name']): ?><div class="actor-card"><strong><?= esc($request['transmitter_name']) ?></strong><div class="small text-muted">Admin (Creative Staff)</div><div class="small"><?= esc(date('M j, Y g:i A', strtotime((string) $request['transmitted_at']))) ?></div></div><?php else: ?>—<?php endif; ?></td><td class="text-end">
<?php if ($canManage && $request['status'] === 'submitted'): ?><button class="btn btn-primary btn-sm" data-bs-toggle="modal" data-bs-target="#transmitModal" data-request-id="<?= (int) $request['id'] ?>" data-request-title="<?= esc($request['title'], 'attr') ?>" data-department="<?= esc($request['department'], 'attr') ?>">Transmit</button><?php elseif ($isDepartment && $request['status'] === 'transmitted'): ?><form action="<?= esc(site_url('workspace/distribution/requests/' . (int) $request['id'] . '/complete')) ?>" method="post"><?= csrf_field() ?><button class="btn btn-success btn-sm" type="submit">Complete</button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if ($requests === []): ?><tr><td colspan="5" class="text-center text-muted py-5">No department requests found.</td></tr><?php endif; ?></tbody></table></div></div></div>
