</section></main>
<?php if ($canManage): ?><div class="modal fade" id="transmitModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form id="transmitForm" method="post"><?= csrf_field() ?><div class="modal-header"><div><h5 class="modal-title">Transmit files</h5><div class="small text-muted" id="transmitContext"></div></div><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="file-picker border rounded p-2"><?php foreach ($files as $file): ?><label class="d-block small py-1"><input class="form-check-input me-2" type="checkbox" name="file_ids[]" value="<?= (int) $file['id'] ?>"><?= esc(\App\Libraries\MediaTitle::forFile($file)) ?></label><?php endforeach; ?></div><input type="hidden" name="department" id="transmitDepartment"></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Transmit</button></div></form></div></div></div><script>document.getElementById('transmitModal').addEventListener('show.bs.modal',function(e){var b=e.relatedTarget;document.getElementById('transmitForm').action=<?= json_encode(rtrim(site_url('workspace/distribution/requests'), '/')) ?>+'/'+b.dataset.requestId+'/transmit';document.getElementById('transmitContext').textContent=b.dataset.requestTitle+' · '+b.dataset.department;document.getElementById('transmitDepartment').value=b.dataset.department;});</script><?php endif; ?>
